// Get the name of the object (singular)
OUString E3dSphereObj::TakeObjNameSingul() const
{
    OUString sName(SvxResId(STR_ObjNameSingulSphere3d));

    OUString aName(GetName());
    if (!aName.isEmpty())
    {
        sName += " '" + aName + "'";
    }
    return sName;
}
